\label{defgen}
Proposition \ref{etalehs} enables us to generalize Definition \ref{hstrdef} in the following way.
\begin{enumerate}
\item Since the localization maps are \'{e}tale (see \cite[p. 193]{mat}), any ($m$-truncated) $e$-dimensional HS-derivation on $R$ uniquely extends to an ($m$-truncated) $e$-dimensional HS-derivation on a localization of $R$.

\item By $(1)$, we get a notion of an ($m$-truncated) $e$-dimensional HS-derivation on any scheme over $k$.

\item Proposition \ref{etalehs} generalizes to schemes over $k$.

\item The notion of an ($m$-truncated) $e$-dimensional HS-derivation on a scheme $V$ is a special case of the notion of a \emph{$\underline{\mathcal{D}}$-structure} on a scheme $V$, see \cite{MS}. We will discuss possible generalizations of the results of this paper to the context of \cite{MS} in Section \ref{msecop}.

\item It is easy to generalize the assumptions of Proposition \ref{etalehs} to include the case of ($m$-truncated) $e$-dimensional HS-derivations \emph{from $R$ to $S$}.
\end{enumerate}

\label{firstdefstrict}
If $\mathbb{D}$ is an ($m$-truncated) $e$-dimensional HS-derivation on $R$ over $k$, then we define the following.
\begin{enumerate}
\item The \emph{ring of constants} of $(R,\mathbb{D})$ is
$$\ker(D_{(1,0,\ldots,0)})\cap \ldots \cap \ker(D_{(0,\ldots,0,1)}).$$
Clearly, $R^p$ is contained in the ring of constants of $(R,\mathbb{D})$.

\item We call $(R,\mathbb{D})$ \emph{strict}, if the ring of constants of $\mathbb{D}$ coincides with $R^p$.

\item The \emph{ring of absolute constants} of $(R,\mathbb{D})$ is
$$\bigcap_{\mathbf{i}\neq \mathbf{0}}\ker(D_{\mathbf{i}}).$$
\end{enumerate}

\begin{enumerate}
\item A \emph{$\mathfrak{g}$-derivation on $V$} is a $k$-group scheme action of $\mathfrak{g}$ on $V$ (see Section 12 in \cite{MuAbel}).

\item A \emph{$\mathfrak{g}$-derivation on $R$} is a $\mathfrak{g}$-derivation on $\mathrm{Spec}(R)$.

\item We naturally get the notions of a \emph{$\mathfrak{g}$-ring}, a \emph{$\mathfrak{g}$-field} and a \emph{$\mathfrak{g}$-extension}.
\end{enumerate}

\label{gderint}
A $\mathfrak{g}$-derivation on $R$ is the same as an $m$-truncated $e$-dimensional
HS-derivation on $R$ over $k$ satisfying a ``$\mathfrak{g}$-iterativity'' rule. It is easy to see that the trivial action of the unit morphism corresponds
to the condition $D_{\mathbf{0}}=\mathrm{id}_R$ and the diagram expressing the mixed associativity of the $k$-group scheme action $d$ is the following ``$\mathfrak{g}$-iterativity'' diagram
\begin{equation*}
\xymatrix{R \ar[r]^d \ar[d]_d & R[\mathbf{v}_m] \ar[d]^{d[\mathbf{v}_m]}
 \\ R[\mathbf{w}_m]\ar[r]^{c} & R[\mathbf{w}_m,\mathbf{v}_m]}
\end{equation*}
where $\mathbf{w}_m$ is another ``$m$-truncated $e$-tuple of variables'' and $c$ is the Hopf algebra comultiplication given by $\mathfrak{g}$. Therefore for an arbitrary $k$-scheme $V$, any $\mathfrak{g}$-derivation on $V$ is also an $m$-truncated $e$-dimensional HS-derivation on $V$ over $k$ in the sense of Remark \ref{defgen}(2).

\begin{equation*}
\xymatrix{R \ar[r]^d \ar[d]_d & R[\mathbf{v}_m] \ar[d]^{d[\mathbf{v}_m]}
 \\ R[\mathbf{w}_m]\ar[r]^{c} & R[\mathbf{w}_m,\mathbf{v}_m]}
\end{equation*}

\label{gderint2}
We will give another interpretation of the $\mathfrak{g}$-iterativity condition. Suppose that the matrix (in the standard basis) of the $k$-linear comultiplication map $c$ from Remark \ref{gderint} has the form $(c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}})$. Suppose also that $\mathbb{D}=(D_{\mathbf{i}})_{\mathbf{i}}$ is an $m$-truncated $e$-dimensional HS-derivation on $R$ over $k$. Then $\mathbb{D}$ is a $\mathfrak{g}$-derivation if and only if for all $\mathbf{i},\mathbf{j}$ we have
$$D_{\mathbf{j}}\circ D_{\mathbf{i}}=\sum_{\mathbf{k}}c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}D_{\mathbf{k}}.$$

\label{frometo1}
